"use client";
import {useState} from "react";
import Input from "@/components/ui/Input";
import {validateStoreSlug} from "@/lib/store/slug";
import s from "./business-workspace.module.css";
export function suggestStoreSlug(name:string){return name.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,64).replace(/-$/g,"");}
export default function StoreIdentityFields({initialName,initialSlug,initialTagline,creating=false}:{initialName:string;initialSlug:string;initialTagline:string;creating?:boolean}){
 const [name,setName]=useState(initialName),[slug,setSlug]=useState(initialSlug),[tagline,setTagline]=useState(initialTagline),[slugEdited,setSlugEdited]=useState(!!initialSlug);
 return <div className={s.stack}><div className={s.hero} style={{padding:22}}><p className={s.label} style={{color:"#c4d6bd"}}>Your first impression · preview</p><h3 style={{fontSize:25,fontWeight:750,letterSpacing:"-.04em",margin:"10px 0 6px",overflowWrap:"anywhere"}}>{name||"Your business name"}</h3><p className={s.muted}>{tagline||"A short line that tells customers what makes you special."}</p></div><Input required label="Store name" name="name" maxLength={120} value={name} placeholder="Your business name" onChange={e=>{setName(e.target.value);if(creating&&!slugEdited)setSlug(suggestStoreSlug(e.target.value));}}/><Input label="Tagline" required={creating} name="tagline" maxLength={200} value={tagline} onChange={e=>setTagline(e.target.value)} helperText={`${tagline.length}/200 characters · What you offer and who it is for.`} placeholder="Thoughtful gifts, handmade in Trinidad"/><Input label="Store web address" name="slug" required minLength={3} maxLength={64} pattern="[a-z0-9]+(-[a-z0-9]+)*" title="3–64 lowercase letters, numbers and single hyphens" value={slug} onChange={e=>{setSlugEdited(true);setSlug(e.target.value.toLowerCase().replaceAll(" ","-"));}} error={slug?validateStoreSlug(slug)??undefined:undefined} helperText={`linkweonlinemall.com/store/${slug||"your-store"}`} className="font-mono"/>{!creating&&slug!==initialSlug&&<p className={s.error}>Changing this address changes your public store link. Update any QR codes and links you have already shared.</p>}</div>;
}
